local function ks(k,n)
 -- 4 字 ARX 分组流：与 rng.keystream / emit_luau n_ks 逐字节一致。
 local M=4294967296
 local a=k%M
 local b=bx(a,608135816)
 local c=bx(a,2242054355)
 local d=bx(a,320440878)
 local o=table.create(n)
 local ctr=0
 local i=0
 local function rl(x,r)
  local p=2^(32-r)
  local lo=x%p
  return (lo*2^r%M+(x-lo)/p)%M
 end
 while i<n do
  local x0,x1,x2,x3=a,b,c,d
  for _=1,4 do
   x0=(x0+x1)%M; x3=rl(bx(x3,x0),16)
   x2=(x2+x3)%M; x1=rl(bx(x1,x2),12)
   x0=(x0+x1)%M; x3=rl(bx(x3,x0),8)
   x2=(x2+x3)%M; x1=rl(bx(x1,x2),7)
  end
  x0=(x0+ctr)%M
  ctr=(ctr+1)%M
  a,b,c,d=x0,x1,x2,x3
  if i+1<=n then o[i+1]=x0%256 end
  if i+2<=n then o[i+2]=(x0-x0%256)/256%256 end
  if i+3<=n then o[i+3]=(x0-x0%65536)/65536%256 end
  if i+4<=n then o[i+4]=(x0-x0%16777216)/16777216%256 end
  if i+5<=n then o[i+5]=x1%256 end
  if i+6<=n then o[i+6]=(x1-x1%256)/256%256 end
  if i+7<=n then o[i+7]=(x1-x1%65536)/65536%256 end
  if i+8<=n then o[i+8]=(x1-x1%16777216)/16777216%256 end
  if i+9<=n then o[i+9]=x2%256 end
  if i+10<=n then o[i+10]=(x2-x2%256)/256%256 end
  if i+11<=n then o[i+11]=(x2-x2%65536)/65536%256 end
  if i+12<=n then o[i+12]=(x2-x2%16777216)/16777216%256 end
  if i+13<=n then o[i+13]=x3%256 end
  if i+14<=n then o[i+14]=(x3-x3%256)/256%256 end
  if i+15<=n then o[i+15]=(x3-x3%65536)/65536%256 end
  if i+16<=n then o[i+16]=(x3-x3%16777216)/16777216%256 end
  i=i+16
 end
 return o
end
local function d85(s)
 local n=#s
 local tail=n%5
 local out=cr((n//5)*4+(tail>0 and tail-1 or 0))
 local at,off=1,0
 while at<=n do
  local cnt=n-at+1
  if cnt>5 then cnt=5 end
  local acc=0
  for j=0,4 do
   local v=84
   if j<cnt then v=byte(s,at+j)-33 end
   acc=acc*85+v
  end
  local take=(cnt==5) and 4 or (cnt-1)
  for j=0,take-1 do
   wr(out,off,floor(acc/2^((3-j)*8))%256)
   off=off+1
  end
  at=at+cnt
 end
 return out,off
end
